    @_documentation(visibility: private)
#endif
    public func uniffiCloneHandle() -> UInt64 {
        return try! rustCall { uniffi_blockself_fn_clone_client(self.handle, $0) }
    }
    // No primary constructor declared for this class.

    deinit {
        if handle == 0 {
            // Mock objects have handle=0 don't try to free them
            return
        }

        try! rustCall { uniffi_blockself_fn_free_client(handle, $0) }
    }

    
public static func login(username: String, password: String, hostId: UInt32?)async throws  -> Client  {
    return
        try  await uniffiRustCallAsync(
            rustFutureFunc: {
                uniffi_blockself_fn_constructor_client_login(FfiConverterString.lower(username),FfiConverterString.lower(password),FfiConverterOptionUInt32.lower(hostId)
                )
