            pollFunc: ffi_blockself_rust_future_poll_u64,
            completeFunc: ffi_blockself_rust_future_complete_u64,
            freeFunc: ffi_blockself_rust_future_free_u64,
            liftFunc: FfiConverterTypeClient_lift,
            errorHandler: FfiConverterTypeHttpError_lift
